"use client";

import { useState, useEffect } from "react";
import { config } from "./config";

export function ApplicationSection() {
  const [mode, setMode] = useState<"business" | "seller">("business");
  const [submitted, setSubmitted] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  // Form fields
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [companyName, setCompanyName] = useState("");
  const [website, setWebsite] = useState("");
  const [description, setDescription] = useState("");
  const [honeypot, setHoneypot] = useState(""); // anti-spam

  useEffect(() => {
    const handleHash = () => {
      if (window.location.hash.includes("mode=seller")) {
        setMode("seller");
      } else if (window.location.hash.includes("mode=business")) {
        setMode("business");
      }
    };

    handleHash();
    window.addEventListener("hashchange", handleHash);
    return () => window.removeEventListener("hashchange", handleHash);
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (honeypot) {
      // Bot detected silently
      setSubmitted(true);
      return;
    }

    if (!name || !email || !phone) {
      setError("Please fill in all required contact fields.");
      return;
    }

    setSubmitting(true);

    try {
      const endpoint = config.formEndpoint;
      if (endpoint.includes("your-form-id")) {
        await new Promise((res) => setTimeout(res, 800));
        setSubmitted(true);
      } else {
        const res = await fetch(endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            type: mode,
            name,
            email,
            phone,
            companyName,
            website,
            description,
          }),
        });
        if (res.ok) {
          setSubmitted(true);
        } else {
          setError("Submission failed. Please try again or contact us via WhatsApp.");
        }
      }
    } catch (err) {
      console.error(err);
      setError("An error occurred. Please try again later.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <section id="apply" className="py-24 border-t border-white/[0.08] bg-[#0B0B0D]">
      <div className="mx-auto max-w-3xl px-6 sm:px-8">
        <div className="text-center mb-12">
          <h2 className="text-xs font-mono uppercase tracking-widest text-[#C7FF4D] mb-3">
            Pilot Application
          </h2>
          <h3 className="text-3xl font-bold tracking-tight text-white sm:text-4xl">
            Apply to join the pilot
          </h3>
          <p className="mt-4 text-zinc-400">
            Early cohort intake is limited to ensure quality matching. Select your track below.
          </p>
        </div>

        <div className="rounded-2xl border border-white/[0.08] bg-[#15151A]/80 p-8 backdrop-blur-md">
          {submitted ? (
            <div className="py-12 text-center">
              <div className="inline-flex items-center justify-center h-12 w-12 rounded-full bg-[#C7FF4D]/10 text-[#C7FF4D] mb-4 border border-[#C7FF4D]/20">
                ✓
              </div>
              <h4 className="text-xl font-bold text-white mb-2">Application Received</h4>
              <p className="text-sm text-zinc-400 max-w-md mx-auto mb-6">
                Thank you for applying to the {config.platformName} pilot. We will review your details and reach out via WhatsApp or email within 48 hours.
              </p>
              <button
                onClick={() => {
                  setSubmitted(false);
                  setName("");
                  setEmail("");
                  setPhone("");
                  setCompanyName("");
                  setWebsite("");
                  setDescription("");
                }}
                className="rounded-full bg-white/[0.08] px-6 py-2.5 text-xs font-medium text-white transition-colors hover:bg-white/[0.12]"
              >
                Submit another response
              </button>
            </div>
          ) : (
            <div>
              {/* Track switcher tabs */}
              <div className="flex rounded-xl bg-black/40 p-1 mb-8 border border-white/[0.06]">
                <button
                  type="button"
                  onClick={() => setMode("business")}
                  className={`flex-1 rounded-lg py-2.5 text-xs font-semibold transition-all ${
                    mode === "business"
                      ? "bg-[#C7FF4D] text-black shadow-sm"
                      : "text-zinc-400 hover:text-white"
                  }`}
                >
                  I&apos;m a Business / SaaS
                </button>
                <button
                  type="button"
                  onClick={() => setMode("seller")}
                  className={`flex-1 rounded-lg py-2.5 text-xs font-semibold transition-all ${
                    mode === "seller"
                      ? "bg-cyan-400 text-black shadow-sm"
                      : "text-zinc-400 hover:text-white"
                  }`}
                >
                  I&apos;m a Sales Partner
                </button>
              </div>

              {error && (
                <div className="mb-6 rounded-xl border border-red-500/20 bg-red-500/10 p-4 text-xs text-red-400">
                  {error}
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-5">
                {/* Honeypot anti-spam field */}
                <input
                  type="text"
                  name="website_url_hp"
                  value={honeypot}
                  onChange={(e) => setHoneypot(e.target.value)}
                  style={{ display: "none" }}
                  tabIndex={-1}
                  autoComplete="off"
                />

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div>
                    <label className="block text-xs font-mono text-zinc-400 mb-2">
                      Full Name <span className="text-[#C7FF4D]">*</span>
                    </label>
                    <input
                      type="text"
                      required
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      placeholder="e.g. Ahmad Razak"
                      className="w-full rounded-xl border border-white/[0.08] bg-black/40 px-4 py-3 text-sm text-white placeholder:text-zinc-600 focus:border-[#C7FF4D] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-mono text-zinc-400 mb-2">
                      Email Address <span className="text-[#C7FF4D]">*</span>
                    </label>
                    <input
                      type="email"
                      required
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="e.g. ahmad@company.my"
                      className="w-full rounded-xl border border-white/[0.08] bg-black/40 px-4 py-3 text-sm text-white placeholder:text-zinc-600 focus:border-[#C7FF4D] focus:outline-none"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div>
                    <label className="block text-xs font-mono text-zinc-400 mb-2">
                      WhatsApp Number <span className="text-[#C7FF4D]">*</span>
                    </label>
                    <input
                      type="text"
                      required
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      placeholder="e.g. +60123456789"
                      className="w-full rounded-xl border border-white/[0.08] bg-black/40 px-4 py-3 text-sm text-white placeholder:text-zinc-600 focus:border-[#C7FF4D] focus:outline-none"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-mono text-zinc-400 mb-2">
                      {mode === "business" ? "Company / SaaS Name" : "Current Role / Background"}
                    </label>
                    <input
                      type="text"
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      placeholder={mode === "business" ? "e.g. Invoicr Sdn Bhd" : "e.g. B2B Sales / Freelance"}
                      className="w-full rounded-xl border border-white/[0.08] bg-black/40 px-4 py-3 text-sm text-white placeholder:text-zinc-600 focus:border-[#C7FF4D] focus:outline-none"
                    />
                  </div>
                </div>

                {mode === "business" && (
                  <div>
                    <label className="block text-xs font-mono text-zinc-400 mb-2">
                      Product Website or Landing Page
                    </label>
                    <input
                      type="text"
                      value={website}
                      onChange={(e) => setWebsite(e.target.value)}
                      placeholder="https://yourproduct.my"
                      className="w-full rounded-xl border border-white/[0.08] bg-black/40 px-4 py-3 text-sm text-white placeholder:text-zinc-600 focus:border-[#C7FF4D] focus:outline-none"
                    />
                  </div>
                )}

                <div>
                  <label className="block text-xs font-mono text-zinc-400 mb-2">
                    {mode === "business"
                      ? "Briefly describe your product & commission offering"
                      : "Describe your experience & B2B sales network in Malaysia"}
                  </label>
                  <textarea
                    rows={4}
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder={
                      mode === "business"
                        ? "We offer cloud ERP for SMEs. Proposing 20% recurring commission..."
                        : "5 years selling HR tech to SMEs across Klang Valley and Penang..."
                    }
                    className="w-full rounded-xl border border-white/[0.08] bg-black/40 px-4 py-3 text-sm text-white placeholder:text-zinc-600 focus:border-[#C7FF4D] focus:outline-none resize-none"
                  />
                </div>

                <button
                  type="submit"
                  disabled={submitting}
                  className={`w-full rounded-full py-3.5 text-sm font-semibold text-black transition-all ${
                    mode === "business"
                      ? "bg-[#C7FF4D] hover:bg-[#b2ef38]"
                      : "bg-cyan-400 hover:bg-cyan-300"
                  } disabled:opacity-50`}
                >
                  {submitting
                    ? "Submitting Application..."
                    : mode === "business"
                    ? "Submit Business Application"
                    : "Submit Seller Application"}
                </button>

                <p className="text-center text-[11px] text-zinc-500 font-mono pt-2">
                  We respect your privacy. No spam, ever.
                </p>
              </form>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}
