"use client";

import { useState } from "react";
import { config } from "./config";

export function FAQ() {
  const [openIdx, setOpenIdx] = useState<number | null>(0);

  const faqs = [
    {
      q: `What is ${config.platformName}?`,
      a: `An early Malaysia-first pilot that connects businesses with independent sales partners. Businesses pay commission only after a verified customer sale.`,
    },
    {
      q: "Is this a job?",
      a: "No. Sellers are independent participants, not employees. There is no fixed salary or guaranteed income; earnings are entirely performance-based.",
    },
    {
      q: "Is this MLM?",
      a: "No. Sellers earn only from their own verified customer sales. There are no downlines, recruitment rewards, joining fees, or forced purchases.",
    },
    {
      q: "How are commissions verified and paid?",
      a: "When a referred customer completes payment, the transaction is logged and verified between the business and the platform. Payouts are disbursed according to the agreed schedule.",
    },
    {
      q: "Who is eligible to apply during the pilot?",
      a: "For businesses: Registered Malaysian entities offering B2B SaaS, software, or digital services. For sellers: Professionals with established networks among Malaysian SMEs or corporate clients.",
    },
  ];

  return (
    <section id="faq" className="py-24 border-t border-white/[0.08] bg-[#0B0B0D]">
      <div className="mx-auto max-w-3xl px-6 sm:px-8">
        <div className="text-center mb-16">
          <h2 className="text-xs font-mono uppercase tracking-widest text-[#C7FF4D] mb-3">
            Got Questions?
          </h2>
          <h3 className="text-3xl font-bold tracking-tight text-white sm:text-4xl">
            Frequently Asked Questions
          </h3>
          <p className="mt-4 text-zinc-400">
            Everything you need to know about the {config.platformName} pilot program.
          </p>
        </div>

        <div className="space-y-4">
          {faqs.map((faq, idx) => {
            const isOpen = openIdx === idx;
            return (
              <div
                key={idx}
                className="rounded-2xl border border-white/[0.08] bg-[#15151A]/60 backdrop-blur-sm overflow-hidden transition-colors"
              >
                <button
                  onClick={() => setOpenIdx(isOpen ? null : idx)}
                  className="flex w-full items-center justify-between p-6 text-left"
                >
                  <span className="font-semibold text-white text-base">
                    {faq.q}
                  </span>
                  <span className="font-mono text-zinc-400 ml-4">
                    {isOpen ? "−" : "+"}
                  </span>
                </button>
                {isOpen && (
                  <div className="px-6 pb-6 text-sm text-zinc-400 leading-relaxed border-t border-white/[0.04] pt-4">
                    {faq.a}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
